const body = $input.first().json.body;

const required = ['company', 'role', 'applied_date'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const validStatuses = ['applied', 'phone_screen', 'interview', 'final_round', 'offer', 'rejected', 'ghosted', 'withdrawn'];
const status = validStatuses.includes(body.status) ? body.status : 'applied';

return [{
  json: {
    valid: true,
    mode: 'log',
    applicationId: `${body.company.toLowerCase().replace(/\s+/g,'-')}-${Date.now()}`,
    company: body.company.trim(),
    role: body.role.trim(),
    appliedDate: body.applied_date,
    status,
    jobUrl: body.job_url || '',
    salaryRange: body.salary_range || '',
    location: body.location || '',
    remotePolicy: body.remote_policy || '',
    contactName: body.contact_name || '',
    contactEmail: body.contact_email || '',
    notes: (body.notes || '').slice(0, 800),
    excitement: Math.min(10, Math.max(1, parseInt(body.excitement) || 5)),
    source: body.source || '',
    loggedAt: new Date().toISOString()
  }
}];

const apps = $input.all().map(r => r.json);
const today = new Date();
today.setHours(0, 0, 0, 0);

const activeStatuses = ['applied', 'phone_screen', 'interview', 'final_round'];

const active = apps.filter(a => activeStatuses.includes(a.status));
const needsFollowUp = [];
const stale = [];
const recentWins = [];
const recentLosses = [];

for (const app of active) {
  const appliedDate = new Date(app.applied_date);
  const lastFollowUp = app.last_follow_up ? new Date(app.last_follow_up) : null;
  const daysSinceApplied = Math.floor((today - appliedDate) / 86400000);
  const daysSinceFollowUp = lastFollowUp
    ? Math.floor((today - lastFollowUp) / 86400000)
    : daysSinceApplied;

  // Follow up after 7 days if applied, 5 days if in interview process
  const followUpThreshold = app.status === 'applied' ? 7 : 5;

  if (daysSinceFollowUp >= followUpThreshold && parseInt(app.follow_up_count || 0) < 2) {
    needsFollowUp.push({
      ...app,
      daysSinceApplied,
      daysSinceFollowUp,
      followUpCount: parseInt(app.follow_up_count || 0)
    });
  }

  if (daysSinceApplied >= 21 && app.status === 'applied') {
    stale.push({ ...app, daysSinceApplied });
  }
}

// Recent outcomes (last 14 days)
const cutoff = new Date(today);
cutoff.setDate(cutoff.getDate() - 14);
for (const app of apps) {
  const logged = new Date(app.logged_at);
  if (logged >= cutoff) {
    if (app.status === 'offer') recentWins.push(app);
    if (app.status === 'rejected' || app.status === 'ghosted') recentLosses.push(app);
  }
}

// Pipeline summary
const byStatus = {};
for (const a of apps) {
  byStatus[a.status] = (byStatus[a.status] || 0) + 1;
}

const responseRate = apps.length > 0
  ? Math.round((apps.filter(a => a.status !== 'applied').length / apps.length) * 100)
  : 0;

return [{
  json: {
    needsFollowUp: needsFollowUp.slice(0, 5),
    stale,
    recentWins,
    recentLosses,
    byStatus,
    totalActive: active.length,
    totalApplications: apps.length,
    responseRate,
    today: today.toISOString().split('T')[0]
  }
}];

values.content:
Review my job search pipeline and generate follow-up emails.

Pipeline overview:
- Total applications: {{ $json.totalApplications }}
- Active (not yet resolved): {{ $json.totalActive }}
- Response rate: {{ $json.responseRate }}%
- Status breakdown: {{ Object.entries($json.byStatus).map(([s,c]) => `${s}: ${c}`).join(', ') }}

Applications needing follow-up ({{ $json.needsFollowUp.length }}):
{{ $json.needsFollowUp.map(a => `- ${a.company} / ${a.role} | Applied: ${a.applied_date} | Status: ${a.status} | Days since last action: ${a.daysSinceFollowUp} | Follow-ups sent: ${a.followUpCount} | Contact: ${a.contact_name || 'unknown'} | Notes: ${a.notes || 'none'}`).join('\n') }}

Stale applications (21+ days, no movement) ({{ $json.stale.length }}):
{{ $json.stale.map(a => `- ${a.company} / ${a.role} | Applied: ${a.applied_date} | ${a.daysSinceApplied} days ago`).join('\n') || 'none' }}

Recent wins: {{ $json.recentWins.map(a => `${a.company}`).join(', ') || 'none' }}
Recent rejections/ghosts: {{ $json.recentLosses.map(a => `${a.company}`).join(', ') || 'none' }}

Generate this JSON:
{
  "pipeline_assessment": "3-4 sentence frank assessment of the search — what's the state, what to prioritize, one honest pattern observation",
  "follow_up_emails": [
    {
      "application_id": "...",
      "company": "...",
      "role": "...",
      "subject": "email subject",
      "body": "email body — short, professional, human, under 100 words. Address to contact_name if known, otherwise generic opener.",
      "urgency": "low | medium | high"
    }
  ],
  "stale_recommendation": "what to do with the stale applications — mark as ghosted, one final email, or something else. One sentence per application or a general recommendation.",
  "one_thing_to_do_today": "the single most impactful action to take today in this job search"
}

