const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse failed', raw } }];
}

const pipeline = $('Analyse Pipeline').first().json;
parsed._pipeline = pipeline;

return [{ json: parsed }];

const d = $input.first().json;
const p = d._pipeline;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const urgencyColor = { high: '#dc2626', medium: '#d97706', low: '#6b7280' };

const emailCards = (d.follow_up_emails || []).map(e => `
  <div style="border:1px solid #e8e4df;border-radius:8px;margin-bottom:16px;overflow:hidden">
    <div style="background:#f8f6f3;padding:10px 16px;display:flex;justify-content:space-between;align-items:center">
      <div><strong style="font-size:14px">${esc(e.company)}</strong> <span style="color:#888;font-size:13px">— ${esc(e.role)}</span></div>
      <span style="font-size:11px;font-weight:600;color:${urgencyColor[e.urgency] || '#888'};text-transform:uppercase">${esc(e.urgency)}</span>
    </div>
    <div style="padding:14px 16px">
      <div style="font-size:12px;color:#888;margin-bottom:4px">Subject: ${esc(e.subject)}</div>
      <div style="font-size:14px;line-height:1.65;white-space:pre-wrap;color:#333">${esc(e.body)}</div>
    </div>
  </div>`).join('');

const statusOrder = ['applied','phone_screen','interview','final_round','offer','rejected','ghosted','withdrawn'];
const statusLabels = { applied:'Applied', phone_screen:'Phone Screen', interview:'Interview', final_round:'Final Round', offer:'Offer 🎉', rejected:'Rejected', ghosted:'Ghosted', withdrawn:'Withdrawn' };
const pipelineRows = statusOrder
  .filter(s => p.byStatus[s])
  .map(s => `<div style="display:flex;justify-content:space-between;font-size:13px;padding:5px 0;border-bottom:1px solid #f0f0f0"><span style="color:#555">${statusLabels[s]||s}</span><span style="font-weight:600">${p.byStatus[s]}</span></div>`)
  .join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:620px;margin:0 auto">
  <div style="background:#18181b;color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#71717a;margin-bottom:4px">Job Search · Daily Update</div>
    <div style="font-size:19px;font-weight:700">${p.totalApplications} applications · ${p.totalActive} active · ${p.responseRate}% response rate</div>
    <div style="margin-top:6px;font-size:13px;color:#a1a1aa">${p.today}</div>
  </div>

  <div style="background:#fff;padding:20px 24px;border-left:1px solid #eee;border-right:1px solid #eee">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Pipeline Assessment</div>
    <p style="margin:0 0 16px;font-size:15px;line-height:1.7;color:#333">${esc(d.pipeline_assessment)}</p>
    <div style="background:#f0f7ff;border-left:3px solid #2563eb;padding:12px 16px;border-radius:0 6px 6px 0;font-size:14px">
      <strong>Today's priority:</strong> ${esc(d.one_thing_to_do_today)}
    </div>
  </div>

  <div style="background:#fff;padding:20px 24px;border:1px solid #eee;border-top:4px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:12px">Pipeline breakdown</div>
    ${pipelineRows}
  </div>

  ${emailCards ? `<div style="background:#fff;padding:20px 24px;border:1px solid #eee;border-top:4px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:14px">Follow-up drafts (${(d.follow_up_emails||[]).length})</div>
    ${emailCards}
  </div>` : ''}

  ${d.stale_recommendation ? `<div style="background:#fff8ed;padding:14px 24px;border:1px solid #fde8b0;font-size:14px;line-height:1.6">
    <strong>Stale applications:</strong> ${esc(d.stale_recommendation)}
  </div>` : ''}

  <div style="background:#18181b;color:#555;font-size:11px;padding:12px 24px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Job Application Tracker · ${p.today}
  </div>
</div>
</body></html>`;

return [{ json: { html, followUpCount: (d.follow_up_emails||[]).length, activeCount: p.totalActive } }];
